WITH prev_events AS (SELECT *, LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) AS prev_reading_ts FROM device_readings), flagged AS (SELECT *, CASE WHEN prev_reading_ts IS NULL OR reading_ts > prev_reading_ts + INTERVAL 45 MINUTES THEN 1 ELSE 0 END AS session_start_flag FROM prev_events), sessions_device_readings AS (SELECT id, device_code, reading_ts, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT id, device_code, session_no, CASE WHEN device_code RLIKE '^(DV-04|DV-03)$' THEN 'EXTENDED' ELSE 'PRIORITY' END AS device_code_zone FROM sessions_device_readings;
